using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Collections.Generic;
namespace VinsPDF {
internal static class Large029Tests {
 public static int Run(string[] args){var log=new List<string>();try{for(int i=2;i<args.Length;i++)using(var e=new PdfEngine()){e.Open(args[i]);int count=e.Count;var time=Stopwatch.StartNew();int[] hits=Enumerable.Range(0,count).Select(p=>e.SearchPage(p,"FRAME",false).Count).ToArray();log.Add(Path.GetFileName(args[i])+" search all pages: "+time.ElapsedMilliseconds+" ms; hits="+hits.Sum());string target=Path.Combine(args[1],Path.GetFileNameWithoutExtension(args[i])+"-reduced.pdf");time.Restart();e.ExportEditableReduced(target,Enumerable.Range(0,count).ToArray(),85);log.Add("editable export: "+time.ElapsedMilliseconds+" ms; "+e.ExportReport+"; bytes="+new FileInfo(target).Length);using(var c=new PdfEngine()){c.Open(target);Version029Tests.Assert(c.Count==count,"Large export count changed");Version029Tests.Assert(Enumerable.Range(0,count).Select(p=>c.SearchPage(p,"FRAME",false).Count).SequenceEqual(hits),"Large export search text changed");Version029Tests.Assert(c.Sizes.SequenceEqual(e.Sizes),"Large export page sizes changed");}log.Add("PASS preserved page count, page sizes and search text across every page");}File.WriteAllLines(Path.Combine(args[1],"large-029.txt"),log);return 0;}catch(Exception ex){log.Add("FAIL "+ex);File.WriteAllLines(Path.Combine(args[1],"large-029.txt"),log);return 1;}}
}
}
